def parse_pairs(s):
    out = {}
    i, n = 0, len(s)
    while i < n:
        if s[i] == ';':
            i += 1
            continue
        j = s.find('=', i)
        if j < 0:
            break
        nxt = s.find(';', i)
        if 0 <= nxt < j:
            i = nxt + 1
            continue
        key = s[i:j].strip()
        k = j + 1
        quoted = k < n and s[k] == "'"
        if quoted:
            e = s.find("'", k + 1)
            if e < 0:
                val, i = s[k + 1:], n
            else:
                val = s[k + 1:e]
                i = e + 1
                while i < n and s[i] != ';':
                    i += 1
                i += 1
        else:
            e = s.find(';', k)
            if e < 0:
                val, i = s[k:], n
            else:
                val, i = s[k:e], e + 1
        if key:
            out[key] = val if quoted else val.strip()
    return out

class Limiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.hits = {}

    def hit(self, key, now):
        ts = [t for t in self.hits.get(key, []) if now - self.window < t <= now]
        if len(ts) < self.limit:
            self.hits.setdefault(key, []).append(now)
            return True
        return False

    def count(self, key, now):
        return len([t for t in self.hits.get(key, []) if now - self.window < t <= now])

